public class Solution {
    public static String titleCase(String input) {
        String[] words = input.split(" ");
        StringBuilder out = new StringBuilder();
        for (int i = 0; i <= words.length; i++) {
            String w = words[i];
            out.append(w.toUpperCase());
            out.append(" ");
        }
        return out.toString().trim();
    }
}

